course = 'Python Programming'
print(len(course))          # This will print the length of the string "Python Programming" to the console, which is 18.
print(course.upper())       # This will print the string "Python Programming" in uppercase to the console.
print(course.lower())       # This will print the string "Python Programming" in lowercase to the console.
print(course.title())       # This will print the string "Python Programming" with the first letter of each word capitalized.
print(course.strip())       # This will print the string "Python Programming" with any leading or trailing whitespace removed.
print(course.find("Programming"))           # This will print the index of the first occurrence of the substring "Programming" in the string "Python Programming".
print(course.replace("Python", "Java"))     # This will print the string "Java Programming" with all occurrences of "Python" replaced with "Java".
print("Python" in course)      # This will print True if the substring "Python" is found in the string "Python Programming", otherwise it will print False.